<?php if($block['type']==='buttons'): ?><div class="block-button-group"><?php foreach($block['items'] as $entry):if($entry['url']===''){continue;} ?><a class="btn secondary" href="<?= e($entry['url']) ?>" rel="noopener noreferrer"><?= icon($entry['icon']) ?><?= e($entry['title']) ?></a><?php endforeach ?></div>
<?php else: ?><div class="block-carousel" data-carousel data-autoplay="<?= !empty($block['autoplay'])?'1':'0' ?>" data-interval="<?= (int)($block['interval']??6)*1000 ?>" role="region" aria-roledescription="<?= t('Carousel') ?>" aria-label="<?= e($block['title']?:tr('Carousel')) ?>">
<div class="carousel-track" id="<?= e($blockId.'-track') ?>" tabindex="0"><?php foreach($block['items'] as $i=>$entry):$desktop=public_image_url((int)$entry['media_id']);$mobile=public_image_url((int)($entry['mobile_media_id']??0)); ?><article class="carousel-slide <?= $desktop!==''?'has-image':'' ?>" role="group" aria-roledescription="<?= t('Slide') ?>" aria-label="<?= (int)$i+1 ?> / <?= count($block['items']) ?>">
<?php if($desktop!==''): ?><picture><?php if($mobile!==''): ?><source media="(max-width:600px)" srcset="<?= e($mobile) ?>"><?php endif ?><img src="<?= e($desktop) ?>" alt="" loading="lazy" width="1400" height="700"></picture><?php endif ?><div class="carousel-copy"><span class="eyebrow"><?= str_pad((string)($i+1),2,'0',STR_PAD_LEFT) ?></span><h3><?= e($entry['title']) ?></h3><?php if($entry['text']!==''): ?><p><?= e($entry['text']) ?></p><?php endif ?><?php if($entry['url']!==''): ?><a class="btn" href="<?= e($entry['url']) ?>" rel="noopener noreferrer"><?= t('Explore') ?><?= icon('arrow') ?></a><?php endif ?></div></article><?php endforeach ?></div>
<div class="carousel-controls" hidden><button type="button" class="icon-button" data-carousel-prev aria-label="<?= t('Previous slide') ?>" aria-controls="<?= e($blockId.'-track') ?>"><?= icon('arrow') ?></button><span data-carousel-count aria-live="off">1 / <?= count($block['items']) ?></span><button type="button" class="icon-button" data-carousel-next aria-label="<?= t('Next slide') ?>" aria-controls="<?= e($blockId.'-track') ?>"><?= icon('arrow') ?></button><?php if(!empty($block['autoplay'])): ?><button type="button" class="btn secondary small" data-carousel-pause data-pause-label="<?= t('Pause carousel') ?>" data-play-label="<?= t('Play carousel') ?>"><?= t('Pause carousel') ?></button><?php endif ?></div></div><?php endif ?>
